{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In a rabbit meningitis model, intravenously administered oritavancin, a closely related lipoglycopeptide sharing the vancomycin core and hydrophobic side-chain modifications, showed only 1–5% CSF penetration, indicating inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In rabbits, [14C]dalbavancin-derived radioactivity in CSF was very low and measurable only at 12 and 24 h postdose, supporting poor CNS penetration for the lipoglycopeptide class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Daptomycin, another large lipopeptide antibiotic, achieved only about 5% of serum concentrations in CSF in a rabbit pneumococcal meningitis model, showing that meningeal inflammation does not confer meaningful CNS exposure for this molecular class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In a human case, daptomycin was undetectable in CSF despite therapeutic serum levels, confirming poor CNS penetration for large lipopeptide antibiotics.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Telavancin is a large, highly polar lipoglycopeptide; direct evidence from closely related oritavancin in rabbit meningitis shows only 1–5% CSF penetration, and dalbavancin and daptomycin similarly show negligible CSF exposure. Therefore meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct telavancin CNS penetration data were provided.",
    "Human CNS penetration data for telavancin are absent.",
    "Inflamed meninges may modestly increase penetration, but available class evidence indicates this remains inadequate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

